function ProofCard({value,label,hint,icon:Icon}:{value:string;label:string;hint:string;icon:any}){return <div className="proof-card"><span className="proof-icon"><Icon size={16}/></span><strong>{value}</strong><b>{label}</b><small>{hint}</small></div>}

function ContextCard({icon:Icon,title,text,onClick}:{icon:any;title:string;text:string;onClick:()=>void}){return <button className="context-card" onClick={onClick}><span className="context-icon"><Icon/></span><h3>{title}</h3><p>{text}</p><span className="card-link">Open <ArrowRight size={16}/></span></button>}

function Storefront({lang,products,onProduct,go,flash}:{lang:Lang;products:Product[];onProduct:(p:Product)=>void;go:(s:string)=>void;flash:(s:string)=>void}){
  const vi=lang==='vi'; const [q,setQ]=useState(''); const [filter,setFilter]=useState('all'); const [section,setSection]=useState<'products'|'story'|'commitments'>('products')
  const shown=products.filter(p=>(filter==='all'||p.status===filter) && txt(p.name,lang).toLowerCase().includes(q.toLowerCase()))
  return <main className="store-page">
    <div className="store-nav"><div className="cocoon-word">COCOON <small>VIETNAM</small></div><nav><button className={section==='products'?'active':''} onClick={()=>setSection('products')}>{vi?'Sản phẩm':'Products'}</button><button className={section==='story'?'active':''} onClick={()=>setSection('story')}>{vi?'Câu chuyện':'Story'}</button><button className={section==='commitments'?'active':''} onClick={()=>setSection('commitments')}>{vi?'Cam kết':'Commitments'}</button></nav><div className="store-icons"><Search size={19}/><ShoppingBag size={19}/></div></div>
    {section==='products'&&<>
      <section className="store-hero"><div><span className="store-kicker">COSMO × COCOON</span><h1>{vi?'Mua sắm với bằng chứng rõ ràng hơn.':'Shop with evidence you can actually inspect.'}</h1><p>{vi?'Danh mục dưới đây dùng sản phẩm và ảnh chính thức từ Cocoon Vietnam. Trạng thái COSMO là dữ liệu minh họa độc lập, không phải đánh giá chính thức của Cocoon.':'The catalog below uses official Cocoon Vietnam products and imagery. COSMO statuses are independent demo data, not official Cocoon ratings.'}</p></div><div className="trust-hero-card"><ShieldCheck size={32}/><b>{vi?'Trust Widget ngay tại điểm mua':'Trust Widget at the point of purchase'}</b><span>{vi?'Mở từng sản phẩm để xem nguồn chính thức, bằng chứng và hồ sơ minh bạch.':'Open each product to inspect official source links, evidence and transparency data.'}</span></div></section>
      <section className="catalog-shell"><div className="catalog-toolbar"><div className="searchbox"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder={vi?'Tìm sản phẩm Cocoon…':'Search Cocoon products…'}/></div><div className="chips"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>{vi?'Tất cả':'All'}</button><button className={filter==='verified'?'active':''} onClick={()=>setFilter('verified')}>{vi?'Đủ bằng chứng':'Verified'}</button><button className={filter==='needs_more'?'active':''} onClick={()=>setFilter('needs_more')}>{vi?'Cần bổ sung':'Needs evidence'}</button><button className={filter==='review'?'active':''} onClick={()=>setFilter('review')}>{vi?'Cần xem lại':'Review'}</button></div></div><div className="product-grid">{shown.map(p=><ProductCard key={p.id} p={p} lang={lang} onClick={()=>onProduct(p)} flash={flash}/>)}</div></section>
    </>}
    {section==='story'&&<section className="brand-content-page"><div className="brand-page-hero"><span className="store-kicker">{vi?'CÂU CHUYỆN COCOON':'COCOON STORY'}</span><h1>{vi?'Hồn Việt trong chai':'Vietnamese soul in a bottle'}</h1><p>{vi?'Cocoon kể câu chuyện mỹ phẩm từ những nguyên liệu gắn với vùng đất Việt Nam. COSMO đưa lớp minh bạch lên trên câu chuyện đó: khách hàng có thể mở nguồn, xem bằng chứng và kiểm tra nội dung ngay tại điểm mua.':'Cocoon builds its product story around ingredients tied to places across Vietnam. COSMO adds a transparency layer so customers can inspect sources and evidence at the point of purchase.'}</p><a className="secondary" href="https://cocoonvietnam.com/trang/cau-chuyen-thuong-hieu" target="_blank" rel="noreferrer"><Globe2 size={16}/>{vi?'Xem nguồn chính thức':'Official Cocoon source'}</a></div><div className="ingredient-story-grid">{[
      ['Bí đao','Việt Nam','Da dầu & da mụn'],['Cà phê Đắk Lắk','Đắk Lắk','Chăm sóc cơ thể'],['Nghệ Hưng Yên','Hưng Yên','Dưỡng sáng'],['Hoa hồng','Cao Bằng','Làm sạch & dưỡng ẩm'],['Sen Hậu Giang','Hậu Giang','Da nhạy cảm']
    ].map(([a,b,c])=><article key={a}><span>{a}</span><h3>{b}</h3><p>{c}</p></article>)}</div><div className="source-note"><Info size={16}/><span>{vi?'':'Content is summarized from Cocoon Vietnam’s official website rather than reproduced verbatim.'}</span></div></section>}
    {section==='commitments'&&<section className="brand-content-page"><div className="brand-page-hero"><span className="store-kicker">{vi?'CAM KẾT & CHỨNG NHẬN':'COMMITMENTS & CERTIFICATIONS'}</span><h1>{vi?'Thuần chay, không thử nghiệm trên động vật và trách nhiệm cộng đồng':'Vegan, cruelty-free and community responsibility'}</h1><p>{vi?'Cocoon xây dựng hệ sản phẩm thuần chay, không thử nghiệm trên động vật và theo đuổi các hoạt động môi trường – cộng đồng như một phần trong cam kết phát triển bền vững.':'According to Cocoon’s website, the brand publishes international certifications and community/environment programs. COSMO exposes the source behind each claim.'}</p></div><div className="commitment-grid"><article><ShieldCheck/><h3>Leaping Bunny</h3><p>{vi?'Cocoon giới thiệu chứng nhận từ Cruelty Free International cho tiêu chuẩn không thử nghiệm trên động vật.':'Cocoon presents Cruelty Free International’s Leaping Bunny certification.'}</p></article><article><CheckCircle2/><h3>The Vegan Society</h3><p>{vi?'Website Cocoon giới thiệu chứng nhận Vegan Society cho sản phẩm thuần chay.':'Cocoon’s website presents Vegan Society certification for vegan products.'}</p></article><article><CheckCircle2/><h3>PETA</h3><p>{vi?'Cocoon công bố tham gia chương trình Beauty Without Bunnies – Animal Test-Free & Vegan.':'Cocoon states participation in PETA’s Beauty Without Bunnies program.'}</p></article><article><RefreshCcw/><h3>{vi?'Tái chế bao bì':'Packaging return'}</h3><p>{vi?'Cocoon duy trì các chương trình thu hồi vỏ chai và khuyến khích tái chế.':'Cocoon runs packaging-return and recycling initiatives.'}</p></article><article><ShieldCheck/><h3>{vi?'Phúc lợi động vật':'Animal welfare'}</h3><p>{vi?'Các hoạt động cộng đồng công khai gồm hỗ trợ cứu trợ chó mèo lang thang.':'Public community work includes support for stray-animal rescue.'}</p></article><article><Globe2/><h3>{vi?'Bảo tồn thiên nhiên':'Conservation'}</h3><p>{vi?'Cocoon công bố các hoạt động nâng cao nhận thức bảo tồn, trong đó có rùa biển tại Côn Đảo.':'Cocoon publishes conservation-awareness initiatives including sea turtles in Con Dao.'}</p></article></div><a className="secondary" href="https://cocoonvietnam.com/trang/gia-tri-cot-loi" target="_blank" rel="noreferrer"><Globe2 size={16}/>{vi?'Nguồn: Giá trị cốt lõi Cocoon':'Source: Cocoon core values'}</a></section>}
  </main>
}

function ProductCard({p,lang,onClick,flash}:{p:Product;lang:Lang;onClick:()=>void;flash:(s:string)=>void}){
  return <article className="product-card"><button className="product-image-wrap" onClick={onClick}><img src={p.image} alt={txt(p.name,lang)}/><StatusBadge status={p.status} lang={lang}/></button><div className="product-info"><small>{txt(p.category,lang)}</small><button className="product-title" onClick={onClick}>{txt(p.name,lang)}</button><div className="rating"><Star size={14} fill="currentColor"/>4.8 <span>· {p.verifiedReviews} verified</span></div><div className="price-row"><b>{formatVnd(p.price)}</b><button className="icon-btn" onClick={()=>flash(lang==='vi'?'Đã thêm vào giỏ minh họa.':'Added to sample cart.')}><Plus size={18}/></button></div><button className="trust-inline" onClick={onClick}><ShieldCheck size={16}/><span>{lang==='vi'?'Hồ sơ COSMO':'COSMO profile'} · {p.trustScore}/100</span><ChevronRight size={15}/></button></div></article>
}

function ProductPage({lang,product,go,flash,openEvidence,openQr}:{lang:Lang;product:Product;go:(s:string)=>void;flash:(s:string)=>void;openEvidence:()=>void;openQr:()=>void}){
  const vi=lang==='vi'; const [hero,setHero]=useState(product.image); const [size,setSize]=useState('100 ml')
  useEffect(()=>setHero(product.image),[product.id])
  return <main className="product-page">
    <button className="back-link" onClick={()=>go('/shop')}><ArrowLeft size={17}/>{vi?'Tất cả sản phẩm':'All products'}</button>
    <section className="product-detail-grid"><div className="gallery"><div className="thumbs">{product.gallery.map((g,i)=><button key={g+i} className={hero===g?'active':''} onClick={()=>setHero(g)}><img src={g}/></button>)}</div><div className="hero-photo"><img src={hero} alt={txt(product.name,lang)}/><span className="photo-note">{vi?'Ảnh chính thức từ Cocoon':'Official Cocoon product image'}</span></div></div>
      <div className="buy-panel"><span className="product-eyebrow">COCOON VIETNAM · {product.sku}</span><h1>{txt(product.name,lang)}</h1><div className="review-line"><Star size={16} fill="currentColor"/>4.8 <span>· {product.verifiedReviews} {vi?'review gắn đơn đã giao':'reviews linked to delivered orders'}</span></div><p className="lead">{txt(product.description,lang)}</p><div className="price-large">{formatVnd(product.price)}</div><label>{vi?'Dung tích':'Size'}</label><div className="option-row">{['100 ml','250 ml','500 ml'].map(s=><button key={s} className={size===s?'selected':''} onClick={()=>setSize(s)}>{s}</button>)}</div><button className="buy-button" onClick={()=>flash(vi?'Đã thêm sản phẩm vào giỏ hàng.':'Product added to cart.')}><ShoppingBag size={19}/>{vi?'Thêm vào giỏ':'Add to cart'}</button>{product.sourceUrl&&<a className="official-source-link" href={product.sourceUrl} target="_blank" rel="noreferrer"><Globe2 size={15}/>{vi?'Xem nguồn sản phẩm trên Cocoon':'View official Cocoon product source'}</a>}
        <div className="trust-widget"><div className="widget-head"><span className="shield"><ShieldCheck/></span><div><b>{vi?'Hồ sơ minh bạch — Có bằng chứng COSMO':'Transparency profile — COSMO evidence'}</b><small>{product.realPhotos} {vi?'ảnh thực tế':'real photos'} · {product.verifiedReviews} {vi?'review xác minh':'verified reviews'} · {product.trustScore}/100</small></div><StatusBadge status={product.status} lang={lang}/></div><p>{vi?'Không chỉ là huy hiệu: mở để xem nguồn, trạng thái từng bằng chứng và lịch sử kiểm tra.':'Not just a badge: open it to inspect sources, evidence status and review history.'}</p><div className="widget-actions"><button className="primary" onClick={openEvidence}><Eye size={16}/>{vi?'Mở bằng chứng':'Open evidence'}</button><button className="ghost" onClick={()=>go(`/trust/${product.slug}`)}><FileSearch size={16}/>{vi?'Hồ sơ đầy đủ':'Full profile'}</button><button className="ghost square" onClick={openQr}><QrCode size={18}/></button></div></div>
        <div className="claim-list">{product.claims.map((c,i)=><div key={i}><CheckCircle2 size={17}/><span>{txt(c,lang)}</span></div>)}</div>
      </div></section>
    <section className="detail-benefits"><div><FileCheck2/><b>{vi?'Nguồn bằng chứng':'Evidence sources'}</b><span>{vi?'Phân biệt rõ doanh nghiệp, khách hàng, dữ liệu giao hàng và COSMO.':'Separates brand, customer, delivery and COSMO sources.'}</span></div><div><Bot/><b>{vi?'AI chỉ nêu tín hiệu':'AI flags signals only'}</b><span>{vi?'Không gắn nhãn thật/giả tuyệt đối; con người xác nhận kết quả.':'No absolute true/false label; people confirm results.'}</span></div><div><Activity/><b>{vi?'Có lịch sử thay đổi':'Change history'}</b><span>{vi?'Mỗi lần bổ sung hoặc công bố đều có mốc thời gian.':'Every update and publication has a timestamp.'}</span></div></section>
  </main>
}

function TrustProfile({lang,product,go,openQr}:{lang:Lang;product:Product;go:(s:string)=>void;openQr:()=>void}){
  const vi=lang==='vi'; const evid=product.evidence.length?product.evidence:[
    {id:'fallback1',title:{vi:'Ảnh sản phẩm thực tế',en:'Real product imagery'},type:'image' as const,source:{vi:'Doanh nghiệp',en:'Brand'},verified:true,date:'2026-09-04',note:{vi:'Đã đối chiếu với ảnh chiến dịch.',en:'Compared against campaign imagery.'}},
    {id:'fallback2',title:{vi:'Đối chiếu review – đơn hàng',en:'Review-order reconciliation'},type:'delivery' as const,source:{vi:'Dữ liệu đơn hàng',en:'Order data'},verified:true,date:'2026-09-05',note:{vi:'Review xác minh chỉ khi có trạng thái giao thành công.',en:'Verified only when a delivered order exists.'}},
  ]
  return <main className="trust-page"><button className="back-link" onClick={()=>go(`/shop/${product.slug}`)}><ArrowLeft size={17}/>{vi?'Về sản phẩm':'Back to product'}</button><section className="trust-header"><div><span className="eyebrow"><ShieldCheck size={16}/>COSMO PUBLIC PROFILE</span><h1>{txt(product.name,lang)}</h1><p>{vi?'Hồ sơ công khai cho biết dữ liệu nào do doanh nghiệp cung cấp, dữ liệu nào được đối chiếu, và nội dung nào còn cần xem lại.':'This public profile shows what the brand supplied, what was reconciled, and what still needs review.'}</p></div><div className="score-card"><div className="score-ring"><strong>{product.trustScore}</strong><small>/100</small></div><StatusBadge status={product.status} lang={lang}/><button className="ghost" onClick={openQr}><QrCode size={17}/>{vi?'Mở QR':'Open QR'}</button></div></section>
    <div className="trust-layout"><section className="trust-main"><h2>{vi?'Bằng chứng đang công khai':'Public evidence'}</h2><div className="evidence-list">{evid.map(e=><div className="evidence-row" key={e.id}><span className="evidence-icon">{e.type==='video'?<Video/>:e.type==='image'?<Image/>:e.type==='delivery'?<ShoppingBag/>:<FileCheck2/>}</span><div className="evidence-copy"><div><b>{txt(e.title,lang)}</b>{e.verified&&<span className="tiny-ok"><Check size={12}/>{vi?'Đã xác nhận':'Confirmed'}</span>}</div><small>{txt(e.source,lang)} · {e.date}</small><p>{txt(e.note,lang)}</p></div><button className="icon-btn"><Eye size={17}/></button></div>)}</div><h2>{vi?'Lịch sử hồ sơ':'Profile history'}</h2><div className="timeline">{['Tạo hồ sơ sản phẩm','Bổ sung ảnh thực tế','COSMO ghi nhận tín hiệu','Người kiểm duyệt xác nhận','Công bố Trust Widget'].map((x,i)=><div key={x}><span>{i+1}</span><div><b>{vi?x:['Profile created','Real imagery added','COSMO signal recorded','Human review confirmed','Trust Widget published'][i]}</b><small>0{1+i}/09/2026 · 10:{12+i*7}</small></div></div>)}</div></section>
      <aside className="trust-aside"><div className="aside-card"><h3>{vi?'Cách đọc hồ sơ':'How to read this profile'}</h3><div className="legend"><span><i className="dot ok"></i>{vi?'Đủ bằng chứng':'Sufficient evidence'}</span><span><i className="dot warn"></i>{vi?'Cần bổ sung':'Needs evidence'}</span><span><i className="dot info"></i>{vi?'Cần xem lại':'Needs review'}</span><span><i className="dot danger"></i>{vi?'Rủi ro cao':'High risk'}</span></div><p>{vi?'Trạng thái phản ánh mức độ đầy đủ và tín hiệu cần kiểm tra tại thời điểm cập nhật, không phải chứng nhận chất lượng tuyệt đối.':'Status reflects evidence completeness and signals at the update time; it is not an absolute quality certification.'}</p></div><div className="aside-card"><h3>{vi?'Nguồn dữ liệu':'Data sources'}</h3><ul><li>{vi?'Doanh nghiệp công bố':'Brand disclosure'}</li><li>{vi?'Ảnh/video thực tế':'Real photos/video'}</li><li>{vi?'Dữ liệu đơn hàng/giao hàng':'Order/delivery data'}</li><li>{vi?'Phân tích tín hiệu COSMO':'COSMO signal analysis'}</li><li>{vi?'Người kiểm duyệt xác nhận':'Human reviewer confirmation'}</li></ul></div></aside></div>
  </main>
}

function AdminPortal({lang,section,products,go,flash,setProducts,openQr}:{lang:Lang;section:AdminSection;products:Product[];go:(s:string)=>void;flash:(s:string)=>void;setProducts:(fn:any)=>void;openQr:(p:Product)=>void}){
  const vi=lang==='vi';const[mobile,setMobile]=useState(false);const[notifications,setNotifications]=useState(false)
  return <main className="admin-page"><aside className={`sidebar ${mobile?'open':''}`}><div className="sidebar-brand"><img className="sidebar-logo" src="/cosmo-icon.svg" alt="COSMO"/><div><b>COSMO</b><small>COCOON Vietnam Workspace</small></div><button className="mobile-close" onClick={()=>setMobile(false)}><X/></button></div><nav>{navItems.map(n=>{const I=n.icon;return <button key={n.id} className={section===n.id?'active':''} onClick={()=>{go(`/admin/${n.id}`);setMobile(false)}}><I size={18}/><span>{lang==='vi'?n.vi:n.en}</span>{section===n.id&&<ChevronRight size={15}/>}</button>})}</nav><div className="sidebar-bottom"><div className="connection"><span className="pulse-dot"></span><div><b>{vi?'Website đang kết nối':'Website connected'}</b><small>COCOON Vietnam</small></div></div><button className="ghost full" onClick={()=>go('/shop')}><Store size={16}/>{vi?'Xem website khách hàng':'Open customer website'}</button></div></aside><section className="admin-content"><div className="admin-header"><button className="menu-btn" onClick={()=>setMobile(true)}><Menu/></button><div><h1>{lang==='vi'?navItems.find(n=>n.id===section)?.vi:navItems.find(n=>n.id===section)?.en}</h1><p>{vi?'COCOON Vietnam · Workspace đồng bộ':'COCOON Vietnam · Synced workspace'}</p></div><div className="admin-head-actions"><div className="notify-wrap"><button className="icon-btn" onClick={()=>setNotifications(v=>!v)}><Bell size={18}/></button>{notifications&&<div className="notification-popover"><b>{vi?'Thông báo gần đây':'Recent notifications'}</b><button onClick={()=>go('/admin/ai')}><AlertTriangle size={15}/><span>{vi?'Kiểm tra 1 nội dung AI cần xem lại':'Review 1 AI content result'}</span></button><button onClick={()=>go('/admin/products')}><FileSearch size={15}/><span>{vi?'2 hồ sơ cần bổ sung bằng chứng':'2 profiles need evidence'}</span></button></div>}</div><div className="avatar">CO</div></div></div>{section==='dashboard'&&<Dashboard lang={lang} products={products} go={go}/>} {section==='products'&&<ProductsAdmin lang={lang} products={products} go={go} flash={flash} setProducts={setProducts}/>} {section==='ai'&&<AILab lang={lang} flash={flash} products={products}/>} {section==='reviews'&&<ReviewsAdmin lang={lang} flash={flash}/>} {section==='widget'&&<WidgetBuilder lang={lang} product={products[0]} go={go} flash={flash} openQr={()=>openQr(products[0])}/>} {section==='complaints'&&<Complaints lang={lang} flash={flash}/>} {section==='reports'&&<Reports lang={lang} flash={flash} products={products}/>} {section==='integrations'&&<Integrations lang={lang} flash={flash}/>} {section==='scope'&&<Scope lang={lang}/>}</section></main>
}

function Dashboard({lang,products,go}:{lang:Lang;products:Product[];go:(s:string)=>void}){
  const vi=lang==='vi'
  const cards=[[String(products.length),vi?'Tổng sản phẩm':'Total products',Package],[String(products.filter(p=>p.status==='verified').length),vi?'Đủ bằng chứng':'Sufficient evidence',ShieldCheck],[String(products.filter(p=>p.status==='needs_more').length),vi?'Cần bổ sung':'Needs evidence',FileSearch],[String(products.filter(p=>p.status==='review').length),vi?'Cần xem lại':'Needs review',Eye],[String(products.filter(p=>p.status==='high_risk').length),vi?'Rủi ro cao':'High risk',AlertTriangle]] as const
  return <div className="admin-body"><div className="notice"><Info size={16}/><span>{vi?'Dữ liệu tổng hợp từ hồ sơ sản phẩm, Trust Widget và lịch sử hoạt động của workspace.':'Metrics are aggregated from product profiles, Trust Widget activity and workspace history.'}</span></div><div className="kpi-grid">{cards.map(([v,l,I])=><div className="kpi-card" key={l}><span className="kpi-icon"><I/></span><div><strong>{v}</strong><span>{l}</span></div></div>)}</div>
    <div className="dashboard-grid"><section className="panel"><div className="panel-title"><div><h2>{vi?'Việc cần xử lý':'Needs attention'}</h2><p>{vi?'Ưu tiên theo trạng thái hồ sơ và tín hiệu rủi ro':'Prioritized by profile status and risk signals'}</p></div><ListChecks/></div><div className="task-list">{dashboardTasks.map(t=><button key={t.id} className="task-row" onClick={()=>go(`/admin/${t.target}`)}><div className="task-main"><b>{txt(t.title,lang)}</b><small>{lang==='vi'?statusMeta[t.status].vi:statusMeta[t.status].en}</small></div><StatusBadge status={t.status} lang={lang}/><ArrowRight size={16}/></button>)}</div></section><section className="panel"><div className="panel-title"><div><h2>{vi?'Funnel Trust Widget':'Trust Widget funnel'}</h2><p>{vi?'30 ngày gần nhất':'Last 30 days'}</p></div><BarChart3/></div><div className="funnel"><Funnel label={vi?'Thấy widget':'Widget seen'} value="12,480" width={100}/><Funnel label={vi?'Mở hồ sơ':'Profile opened'} value="3,120" width={72}/><Funnel label={vi?'Thêm giỏ':'Added to cart'} value="624" width={46}/><Funnel label={vi?'Mua hàng':'Purchased'} value="286" width={30}/></div><small className="caveat">{vi?'Tỷ lệ chuyển đổi được ghi nhận từ Trust Widget trong kỳ.':'Conversion rates recorded from Trust Widget activity in this period.'}</small></section></div>
    <section className="panel"><div className="panel-title"><div><h2>{vi?'Sản phẩm gần đây':'Recent products'}</h2><p>{vi?'Click từng dòng để mở hồ sơ':'Click any row to inspect the profile'}</p></div><button className="ghost" onClick={()=>go('/admin/products')}>{vi?'Xem tất cả':'View all'}<ArrowRight size={15}/></button></div><div className="table-wrap"><table><thead><tr><th>{vi?'Sản phẩm':'Product'}</th><th>SKU</th><th>{vi?'Trạng thái':'Status'}</th><th>{vi?'Điểm':'Score'}</th><th>{vi?'Cập nhật':'Updated'}</th></tr></thead><tbody>{products.slice(0,6).map(p=><tr key={p.id} onClick={()=>go('/admin/products')}><td><div className="table-product"><img src={p.image}/><span>{txt(p.name,lang)}</span></div></td><td>{p.sku}</td><td><StatusBadge status={p.status} lang={lang}/></td><td>{p.trustScore}/100</td><td>{p.updated}</td></tr>)}</tbody></table></div></section></div>
}

function Funnel({label,value,width}:{label:string;value:string;width:number}){return <div className="funnel-row"><div><span>{label}</span><b>{value}</b></div><div className="funnel-track"><span style={{width:`${width}%`}}></span></div></div>}

function ProductsAdmin({lang,products,go,flash,setProducts}:{lang:Lang;products:Product[];go:(s:string)=>void;flash:(s:string)=>void;setProducts:(fn:any)=>void}){
  const vi=lang==='vi';const[selectedId,setSelectedId]=useState(products[0]?.id||'');const[extras,setExtras]=useState<any[]>([]);const[busy,setBusy]=useState(false);const selected=products.find(p=>p.id===selectedId)||products[0]
  const loadExtras=async()=>{try{const state=await loadAppState(`evidence:${selected.id}:`);setExtras(Object.values(state))}catch{setExtras([])}}
  useEffect(()=>{if(selected)loadExtras()},[selected?.id])
  const persistProduct=async(status:TrustStatus)=>{if(!selected)return;const score=status==='verified'?Math.max(selected.trustScore,88):status==='high_risk'?Math.min(selected.trustScore,55):selected.trustScore;setProducts((prev:Product[])=>prev.map(p=>p.id===selected.id?{...p,status,trustScore:score,updated:new Date().toISOString().slice(0,10)}:p));await saveAppState(`product:${selected.id}`,{status,trustScore:score,updated:new Date().toISOString()});await logActivity('product_status_changed','product',selected.id,{status,trustScore:score});flash(vi?'Đã lưu trạng thái vào workspace.':'Product status saved to workspace.')}
  const addEvidence=async(file:File)=>{if(!selected)return;setBusy(true);try{const hash=await sha256File(file);const row={name:file.name,type:file.type||'application/octet-stream',size:file.size,sha256:hash,createdAt:new Date().toISOString()};await saveAppState(`evidence:${selected.id}:${Date.now()}`,row);await logActivity('evidence_added','product',selected.id,row);await loadExtras();flash(vi?'Bằng chứng đã được ghi nhận và lưu lịch sử.':'Evidence recorded and saved to history.')}finally{setBusy(false)}}
  if(!selected)return null
  return <div className="admin-body"><div className="master-detail"><section className="panel product-list-panel"><div className="panel-title"><div><h2>{vi?'Danh mục sản phẩm':'Product catalog'}</h2><p>{products.length} {vi?'sản phẩm đang quản lý':'managed products'}</p></div></div><div className="admin-product-list">{products.map(p=><button key={p.id} className={p.id===selected.id?'selected':''} onClick={()=>setSelectedId(p.id)}><img src={p.image}/><div><b>{txt(p.name,lang)}</b><small>{p.sku}</small></div><StatusBadge status={p.status} lang={lang}/></button>)}</div></section><section className="panel product-workspace"><div className="product-work-head"><img src={selected.image}/><div><small>{selected.sku}</small><h2>{txt(selected.name,lang)}</h2><StatusBadge status={selected.status} lang={lang}/></div><button className="ghost" onClick={()=>go(`/trust/${selected.slug}`)}><Globe2 size={16}/>{vi?'Hồ sơ công khai':'Public profile'}</button></div><div className="workspace-stats"><div><strong>{selected.trustScore}/100</strong><span>{vi?'Điểm minh bạch':'Transparency score'}</span></div><div><strong>{selected.realPhotos}</strong><span>{vi?'Ảnh nguồn':'Source images'}</span></div><div><strong>{selected.verifiedReviews}</strong><span>{vi?'Review xác minh':'Verified reviews'}</span></div></div><h3>{vi?'Bằng chứng đã ghi nhận':'Recorded evidence'}</h3><div className="saved-evidence"><div><FileCheck2 size={17}/><span>{vi?'Ảnh sản phẩm chính thức':'Official product imagery'}</span><small>{vi?'Đã xác nhận':'Confirmed'}</small></div>{extras.map((e:any,i)=><div key={i}><FileCheck2 size={17}/><span>{e.name}</span><small>SHA-256 {String(e.sha256||'').slice(0,10)}…</small></div>)}</div><div className="product-actions"><label className="secondary file-action"><Upload size={16}/>{busy?(vi?'Đang lưu…':'Saving…'):(vi?'Thêm bằng chứng':'Add evidence')}<input type="file" onChange={e=>{const f=e.target.files?.[0];if(f)addEvidence(f)}}/></label><button className="ghost" onClick={()=>persistProduct('review')}><Eye size={16}/>{vi?'Chuyển xem lại':'Send to review'}</button><button className="primary" onClick={()=>persistProduct('verified')}><CheckCircle2 size={16}/>{vi?'Xác nhận đủ bằng chứng':'Confirm evidence'}</button></div></section></div></div>
}

function AILab({lang,flash,products}:{lang:Lang;flash:(s:string)=>void;products:Product[]}){
  const vi=lang==='vi';const[type,setType]=useState<'video'|'image'|'audio'|'text'|'compare'>('image');const[running,setRunning]=useState(false);const[progress,setProgress]=useState(0);const[file,setFile]=useState<File|null>(null);const[preview,setPreview]=useState('');const[productSlug,setProductSlug]=useState(products[0]?.slug);const[technical,setTechnical]=useState<Array<{label:string;value:string;note?:string}>>([]);const[imageAI,setImageAI]=useState<ImageForensicsResult|null>(null);const[videoAI,setVideoAI]=useState<VideoForensicsResult|null>(null);const[audioAI,setAudioAI]=useState<AudioForensicsResult|null>(null);const[modelError,setModelError]=useState('');const selectedProduct=products.find(p=>p.slug===productSlug)||products[0]
  useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview])
  const reset=()=>{setTechnical([]);setImageAI(null);setVideoAI(null);setAudioAI(null);setModelError('');setProgress(0)}
  const setLocalFile=(f:File|null)=>{if(preview)URL.revokeObjectURL(preview);setFile(f);setPreview(f?URL.createObjectURL(f):'');reset()}
  const loadSample=async(kind:'video'|'audio')=>{const url=kind==='video'?'/sample-scan.mp4':'/media/cocoon-synthetic-voice.wav';const name=kind==='video'?'cocoon-product-check.mp4':'cocoon-synthetic-voice.wav';const mime=kind==='video'?'video/mp4':'audio/wav';const r=await fetch(url);setLocalFile(new File([await r.blob()],name,{type:mime}))}
  const analyzeImage=async(blob:Blob)=>{const bitmap=await createImageBitmap(blob);try{const c=document.createElement('canvas');c.width=64;c.height=64;const ctx=c.getContext('2d')!;ctx.drawImage(bitmap,0,0,64,64);const d=ctx.getImageData(0,0,64,64).data;let lum=0,edge=0;for(let i=0;i<d.length;i+=4)lum+=(d[i]+d[i+1]+d[i+2])/3;for(let y=0;y<64;y++)for(let x=1;x<64;x++){const i=(y*64+x)*4,j=i-4;edge+=Math.abs(d[i]-d[j])+Math.abs(d[i+1]-d[j+1])+Math.abs(d[i+2]-d[j+2])}return[{label:vi?'Kích thước ảnh':'Image dimensions',value:`${bitmap.width} × ${bitmap.height}px`},{label:vi?'Độ sáng trung bình':'Mean brightness',value:`${Math.round(lum/(d.length/4))}/255`},{label:vi?'Năng lượng biên':'Edge energy',value:Math.round(edge/(64*63*3)).toString()}]}finally{bitmap.close()}}
  const analyzeAudio=async(f:File)=>{const ac=new AudioContext();const b=await ac.decodeAudioData(await f.arrayBuffer());const ch=b.getChannelData(0);let sq=0,peak=0,clip=0,zc=0;for(let i=0;i<ch.length;i++){const a=Math.abs(ch[i]);sq+=a*a;if(a>peak)peak=a;if(a>.99)clip++;if(i>0&&((ch[i]>=0)!==(ch[i-1]>=0)))zc++}await ac.close();return[{label:vi?'Thời lượng':'Duration',value:`${b.duration.toFixed(2)} s`},{label:vi?'Tần số lấy mẫu':'Sample rate',value:`${b.sampleRate} Hz`},{label:'RMS',value:Math.sqrt(sq/ch.length).toFixed(4)},{label:vi?'Đỉnh tín hiệu':'Peak',value:peak.toFixed(4)},{label:vi?'Tỷ lệ clipping':'Clipping ratio',value:`${(clip/ch.length*100).toFixed(3)}%`},{label:'Zero-crossing rate',value:(zc/ch.length).toFixed(4)}]}
  const analyzeVideo=async(f:File)=>await new Promise<Array<{label:string;value:string}>>((resolve,reject)=>{const u=URL.createObjectURL(f);const v=document.createElement('video');v.preload='metadata';v.onloadedmetadata=()=>{resolve([{label:vi?'Thời lượng':'Duration',value:`${v.duration.toFixed(2)} s`},{label:vi?'Độ phân giải':'Resolution',value:`${v.videoWidth} × ${v.videoHeight}`},{label:vi?'Dung lượng':'File size',value:`${(f.size/1024/1024).toFixed(2)} MB`}]);URL.revokeObjectURL(u)};v.onerror=()=>{URL.revokeObjectURL(u);reject(new Error('video metadata'))};v.src=u})
  const run=async()=>{setRunning(true);setProgress(6);setModelError('');try{let active=file;let payload:any={mediaType:type,product:selectedProduct.id};if(type==='image'||type==='compare'){let blob:Blob;if(active)blob=active;else blob=await (await fetch(selectedProduct.image)).blob();setTechnical(await analyzeImage(blob));setProgress(28);const ai=await classifyBlob(blob);setImageAI(ai);payload={...payload,model:ai.model,fakeProbability:ai.fakeProbability,verdict:ai.verdict};setProgress(100)}else if(type==='video'){if(!active){await loadSample('video');const r=await fetch('/sample-scan.mp4');active=new File([await r.blob()],'cocoon-product-check.mp4',{type:'video/mp4'})}setTechnical(await analyzeVideo(active));const ai=await classifyVideoFile(active,(d,t)=>setProgress(20+Math.round(d/t*75)));setVideoAI(ai);payload={...payload,model:ai.model,averageFakeProbability:ai.averageFakeProbability,maxFakeProbability:ai.maxFakeProbability,verdict:ai.verdict};setProgress(100)}else if(type==='audio'){if(!active){const r=await fetch('/media/cocoon-synthetic-voice.wav');active=new File([await r.blob()],'cocoon-synthetic-voice.wav',{type:'audio/wav'});setLocalFile(active)}setTechnical(await analyzeAudio(active));setProgress(35);const ai=await classifyAudioFile(active);setAudioAI(ai);payload={...payload,model:ai.model,spoofProbability:ai.spoofProbability,bonaFideProbability:ai.bonaFideProbability,verdict:ai.verdict};setProgress(100)}else{setTechnical([{label:vi?'Độ dài mô tả':'Description length',value:`${txt(selectedProduct.description,lang).length} chars`},{label:vi?'Số claim đang theo dõi':'Tracked claims',value:String(selectedProduct.claims.length)},{label:vi?'Nguồn':'Source',value:'cocoonvietnam.com'}]);payload={...payload,claims:selectedProduct.claims.length};setProgress(100)}await logActivity('ai_scan_completed','product',selectedProduct.id,payload);await saveAppState(`scan:last:${type}`,{...payload,createdAt:new Date().toISOString()})}catch(e:any){setModelError(e?.message||String(e))}finally{setTimeout(()=>setRunning(false),250)}}
  const p=(n:number)=>`${(n*100).toFixed(1)}%`
  return <div className="admin-body"><div className="ai-intro"><div><span className="eyebrow"><Bot size={16}/>{vi?'PHÒNG KIỂM TRA ĐA PHƯƠNG TIỆN':'MULTIMEDIA INSPECTION LAB'}</span><h2>{vi?'Kiểm tra ảnh, video và giọng nói bằng các model chạy trực tiếp trên media.':'Inspect images, video and voice with models running directly on the media.'}</h2><p>{vi?'Kết quả được tạo tại thời điểm phân tích và lưu vào lịch sử workspace.':'Results are generated at analysis time and stored in the workspace history.'}</p></div></div><div className="model-live-banner"><span className="model-live-dot"></span><div><b>{vi?'Bộ máy phân tích đang hoạt động':'Analysis engines online'}</b><small>DeepfakeDet-ViT · AASIST · ONNX Runtime Web</small></div></div><div className="toolbar ai-toolbar"><div className="ai-tabs">{[['image',Image,vi?'Hình ảnh':'Image'],['video',Video,'Video'],['audio',Activity,vi?'Âm thanh':'Audio'],['text',MessageSquareText,vi?'Văn bản & review':'Text & reviews'],['compare',RefreshCcw,vi?'Đối chiếu ảnh':'Image compare']].map(([id,I,l]:any)=>{const Icon=I;return <button key={id} className={type===id?'active':''} onClick={()=>{setType(id);setLocalFile(null)}}><Icon size={17}/>{l}</button>})}</div><div className="product-select"><label>{vi?'Sản phẩm':'Product'}</label><select value={productSlug} onChange={e=>{setProductSlug(e.target.value);reset()}}>{products.map(p=> <option key={p.id} value={p.slug}>{txt(p.name,lang)}</option>)}</select></div></div><div className="ai-grid"><section className="panel media-panel"><div className="panel-title"><div><h2>{vi?'Nội dung cần kiểm tra':'Content to inspect'}</h2><p>{txt(selectedProduct.name,lang)} · COCOON Vietnam</p></div><span className="real-source-badge"><CheckCircle2 size={14}/>{vi?'Đã liên kết nguồn':'Source linked'}</span></div><div className="asset-head"><img src={selectedProduct.image}/><div><small>{selectedProduct.sku}</small><b>{txt(selectedProduct.name,lang)}</b>{selectedProduct.sourceUrl&&<a href={selectedProduct.sourceUrl} target="_blank" rel="noreferrer">{vi?'Mở trang sản phẩm':'Open product page'} <ArrowRight size={13}/></a>}</div></div>{type==='image'?<div className="image-inspect"><img src={preview||selectedProduct.image}/><div className="inspect-note"><b>{file?file.name:(vi?'Ảnh sản phẩm đã liên kết':'Linked product image')}</b><p>{vi?'COSMO đo pixel và chạy detector ảnh AI trong cùng một lần phân tích.':'COSMO measures pixels and runs the AI-image detector in one analysis.'}</p></div></div>:type==='video'?<div className="official-media"><iframe src="https://www.youtube.com/embed/rH86s5h8yQs?rel=0" title="Cocoon Vietnam video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowFullScreen></iframe><div className="sample-actions"><button className="secondary" onClick={()=>loadSample('video')}><Video size={16}/>{vi?'Dùng video kiểm thử sản phẩm':'Use product test video'}</button>{file&&<span>{file.name}</span>}</div></div>:type==='audio'?<div className="audio-live"><audio controls src={preview||'/media/cocoon-synthetic-voice.wav'}/><div className="sample-actions"><button className="secondary" onClick={()=>loadSample('audio')}><Activity size={16}/>{vi?'Dùng mẫu giọng tổng hợp kiểm thử':'Use synthetic voice control'}</button>{file&&<span>{file.name}</span>}</div><p>{vi?'Mẫu kiểm thử đọc mô tả sản phẩm Cocoon và được dùng như positive control cho detector giọng giả.':'The control reads Cocoon product copy and is used as a synthetic-voice positive control.'}</p></div>:type==='text'?<div className="text-inspect"><div className="claim-card"><small>{vi?'Mô tả sản phẩm':'Product description'}</small><b>{txt(selectedProduct.name,lang)}</b><p>{txt(selectedProduct.description,lang)}</p></div><div className="claim-list">{selectedProduct.claims.map((c,i)=><div key={i}><CheckCircle2 size={17}/><span>{txt(c,lang)}</span></div>)}</div></div>:<div className="compare-inspect"><div><small>{vi?'Ảnh nguồn':'Source image'}</small><img src={selectedProduct.image}/></div><div><small>{file?(vi?'Ảnh đối chiếu':'Comparison image'):(vi?'Tải ảnh đối chiếu':'Upload comparison')}</small>{preview?<img src={preview}/>:<div className="empty-compare">{vi?'Chọn ảnh để chạy đối chiếu.':'Choose an image to compare.'}</div>}</div></div>}<label className="upload-bar"><Upload size={18}/><div><b>{file?.name||(vi?'Chọn file media':'Choose media file')}</b><small>{vi?'Media được phân tích trực tiếp trên thiết bị.':'Media is analyzed directly on-device.'}</small></div><input type="file" accept={type==='video'?'video/*':type==='audio'?'audio/*':type==='image'||type==='compare'?'image/*':'*/*'} onChange={e=>setLocalFile(e.target.files?.[0]||null)}/></label><button className="primary full large" disabled={running} onClick={run}>{running?<><RefreshCcw className="spin" size={18}/>{vi?'Đang phân tích…':'Analyzing…'} {progress}%</>:<><ScanSearch size={18}/>{vi?'Chạy phân tích AI':'Run AI analysis'}</>}</button>{running&&<div className="progress"><span style={{width:`${progress}%`}}/></div>}</section><section className="panel result-panel real-analysis-panel"><div className="result-head"><div><small>{vi?'KẾT QUẢ PHÂN TÍCH':'ANALYSIS RESULT'}</small><h2>{imageAI||videoAI||audioAI||technical.length?(vi?'Hoàn tất':'Complete'):(vi?'Sẵn sàng':'Ready')}</h2></div><span className="real-source-badge"><Database size={14}/>{vi?'Đã lưu lịch sử':'History enabled'}</span></div>{modelError&&<div className="analysis-error">{modelError}</div>}{imageAI&&<div className="ai-verdict-card"><strong>{imageAI.verdict==='likely_fake'?(vi?'Có tín hiệu ảnh AI':'AI-image signals detected'):(vi?'Thiên về ảnh thật':'Leans real')}</strong><div><span>{vi?'Khả năng AI':'AI-generated'} <b>{p(imageAI.fakeProbability)}</b></span><span>{vi?'Khả năng ảnh thật':'Real'} <b>{p(imageAI.realProbability)}</b></span></div><small>{imageAI.model} · {Math.round(imageAI.elapsedMs)} ms</small></div>}{videoAI&&<div className="ai-verdict-card"><strong>{videoAI.verdict==='likely_fake'?(vi?'Video có nhiều frame rủi ro':'Video contains high-risk frames'):videoAI.verdict==='mixed'?(vi?'Tín hiệu frame hỗn hợp':'Mixed frame signals'):(vi?'Các frame thiên về ảnh thật':'Frames lean real')}</strong><div><span>{vi?'Trung bình AI':'Average AI'} <b>{p(videoAI.averageFakeProbability)}</b></span><span>{vi?'Frame cao nhất':'Max frame'} <b>{p(videoAI.maxFakeProbability)}</b></span></div><div className="frame-grid">{videoAI.frames.map((f,i)=><span key={i}>t={f.time.toFixed(1)}s · {p(f.fakeProbability)}</span>)}</div></div>}{audioAI&&<div className="ai-verdict-card audio-verdict"><strong>{audioAI.verdict==='likely_spoof'?(vi?'Có tín hiệu giọng giả':'Spoofed-voice signals detected'):(vi?'Thiên về giọng thật':'Leans bona fide')}</strong><div><span>{vi?'Spoof signal':'Spoof signal'} <b>{p(audioAI.spoofProbability)}</b></span><span>{vi?'Bona fide':'Bona fide'} <b>{p(audioAI.bonaFideProbability)}</b></span></div><small>{audioAI.model} · {Math.round(audioAI.elapsedMs)} ms</small></div>}{technical.length>0&&<div className="technical-results">{technical.map((r,i)=><div key={i}><span>{r.label}</span><strong>{r.value}</strong>{r.note&&<small>{r.note}</small>}</div>)}</div>}{!imageAI&&!videoAI&&!audioAI&&!technical.length&&!modelError&&<div className="analysis-empty"><ScanSearch size={36}/><h3>{vi?'Chọn media và chạy phân tích':'Choose media and run analysis'}</h3><p>{vi?'Kết quả model và thông số kỹ thuật sẽ xuất hiện tại đây.':'Model results and technical measurements will appear here.'}</p></div>}<div className="method-note"><ShieldCheck size={17}/><p>{vi?'Điểm model là tín hiệu hỗ trợ kiểm duyệt và được lưu cùng thời điểm, model và media nguồn.':'Model scores are review signals stored together with timestamp, model and source media.'}</p></div></section></div></div>
}

function ReviewsAdmin({lang,flash}:{lang:Lang;flash:(s:string)=>void}){
  const vi=lang==='vi';const base=[{id:'r1',name:'Trần Minh Quân',rating:5,order:'CC-88421',verified:true,review:false},{id:'r2',name:'Lê Thu Hà',rating:4,order:'CC-88377',verified:true,review:false},{id:'r3',name:'Nguyễn Đức Anh',rating:5,order:'—',verified:false,review:true},{id:'r4',name:'Phạm Bảo Ngọc',rating:3,order:'CC-88190',verified:true,review:false},{id:'r5',name:'Vũ Hoàng Nam',rating:4,order:'CC-90112',verified:true,review:false}];const[rows,setRows]=useState(base);const[filter,setFilter]=useState('all')
  useEffect(()=>{loadAppState('review:').then(s=>setRows(prev=>prev.map(r=>({...r,...(s[`review:${r.id}`]||{})})))).catch(()=>{})},[])
  const update=async(id:string,patch:any)=>{setRows(prev=>prev.map(r=>r.id===id?{...r,...patch}:r));await saveAppState(`review:${id}`,patch);await logActivity('review_updated','review',id,patch);flash(vi?'Review đã được cập nhật và lưu.':'Review updated and saved.')}
  const visible=rows.filter(r=>filter==='all'||filter==='verified'&&r.verified||filter==='review'&&r.review)
  return <div className="admin-body"><div className="toolbar"><div className="chips"><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>{vi?'Tất cả':'All'}</button><button className={filter==='verified'?'active':''} onClick={()=>setFilter('verified')}>{vi?'Đã xác minh giao dịch':'Transaction verified'}</button><button className={filter==='review'?'active':''} onClick={()=>setFilter('review')}>{vi?'Cần xem lại':'Needs review'}</button></div></div><section className="panel"><div className="table-wrap"><table><thead><tr><th>{vi?'Khách hàng':'Customer'}</th><th>{vi?'Đánh giá':'Rating'}</th><th>{vi?'Mã đơn':'Order'}</th><th>{vi?'Xác minh':'Verification'}</th><th>{vi?'Kiểm duyệt':'Review status'}</th><th></th></tr></thead><tbody>{visible.map(r=><tr key={r.id}><td>{r.name}</td><td>★ {r.rating}</td><td>{r.order}</td><td>{r.verified?<span className="tiny-ok"><Check size={12}/>{vi?'Đơn đã giao':'Delivered order'}</span>:<button className="ghost" onClick={()=>update(r.id,{verified:true})}>{vi?'Xác minh đơn':'Verify order'}</button>}</td><td>{r.review?<StatusBadge status="review" lang={lang}/>:<span className="tiny-ok"><Check size={12}/>{vi?'Đã duyệt':'Cleared'}</span>}</td><td><button className="ghost" onClick={()=>update(r.id,{review:!r.review})}>{r.review?(vi?'Đánh dấu đã duyệt':'Mark cleared'):(vi?'Cần xem lại':'Flag review')}</button></td></tr>)}</tbody></table></div></section></div>
}

function WidgetBuilder({lang,product,go,flash,openQr}:{lang:Lang;product:Product;go:(s:string)=>void;flash:(s:string)=>void;openQr:()=>void}){
  const vi=lang==='vi';const[settings,setSettings]=useState({style:'transparency_card',showStatus:true,showPhotos:true,showReviews:true,showUpdated:true});const[saving,setSaving]=useState(false)
  useEffect(()=>{loadAppState('widget:settings').then(s=>{if(s['widget:settings'])setSettings((v:any)=>({...v,...s['widget:settings']}))}).catch(()=>{})},[])
  const save=async()=>{setSaving(true);try{await saveAppState('widget:settings',settings);await logActivity('widget_settings_saved','widget','cosmo-demo',settings);flash(vi?'Trust Widget đã được lưu và đồng bộ.':'Trust Widget saved and synchronized.')}finally{setSaving(false)}}
  const toggle=(key:string)=>(e:any)=>setSettings((s:any)=>({...s,[key]:e.target.checked}))
  return <div className="admin-body"><div className="widget-builder-grid"><section className="panel"><div className="panel-title"><div><h2>{vi?'Cấu hình Trust Widget':'Trust Widget settings'}</h2><p>{vi?'Các thay đổi được lưu vào workspace.':'Changes are stored in the workspace.'}</p></div></div><label className="field-label">{vi?'Kiểu hiển thị':'Display style'}</label><div className="chips"><button className={settings.style==='badge'?'active':''} onClick={()=>setSettings(s=>({...s,style:'badge'}))}>Badge</button><button className={settings.style==='transparency_card'?'active':''} onClick={()=>setSettings(s=>({...s,style:'transparency_card'}))}>{vi?'Thẻ minh bạch':'Transparency card'}</button><button className={settings.style==='floating_button'?'active':''} onClick={()=>setSettings(s=>({...s,style:'floating_button'}))}>{vi?'Nút nổi':'Floating button'}</button></div><div className="setting-list"><label><span>{vi?'Hiện trạng thái':'Show status'}</span><input type="checkbox" checked={settings.showStatus} onChange={toggle('showStatus')}/></label><label><span>{vi?'Hiện số ảnh nguồn':'Show source photos'}</span><input type="checkbox" checked={settings.showPhotos} onChange={toggle('showPhotos')}/></label><label><span>{vi?'Hiện review xác minh':'Show verified reviews'}</span><input type="checkbox" checked={settings.showReviews} onChange={toggle('showReviews')}/></label><label><span>{vi?'Hiện ngày cập nhật':'Show updated date'}</span><input type="checkbox" checked={settings.showUpdated} onChange={toggle('showUpdated')}/></label></div><button className="primary full" disabled={saving} onClick={save}>{saving?(vi?'Đang lưu…':'Saving…'):(vi?'Lưu & đồng bộ widget':'Save & sync widget')}</button></section><section className="panel"><div className="panel-title"><div><h2>{vi?'Xem trước trên website':'Website preview'}</h2><p>{txt(product.name,lang)}</p></div></div><div className="browser-preview"><div className="browser-bar"><span></span><span></span><span></span><small>{`cocoonvietnam.com/products/${product.slug}`}</small></div><div className="browser-body"><img src={product.image}/><h3>{txt(product.name,lang)}</h3><div className={`trust-widget widget-preview style-${settings.style}`}><div className="widget-head"><ShieldCheck/><div><b>COSMO Trust Profile</b>{settings.showStatus&&<StatusBadge status={product.status} lang={lang}/>}</div></div>{settings.showPhotos&&<small>{product.realPhotos} {vi?'ảnh nguồn':'source photos'}</small>}{settings.showReviews&&<small>{product.verifiedReviews} {vi?'review xác minh':'verified reviews'}</small>}{settings.showUpdated&&<small>{vi?'Cập nhật':'Updated'}: {product.updated}</small>}<div className="widget-actions"><button className="primary" onClick={()=>go(`/trust/${product.slug}`)}>{vi?'Mở hồ sơ':'Open profile'}</button><button className="ghost square" onClick={openQr}><QrCode size={17}/></button></div></div></div></div></section></div></div>
}

function Complaints({lang,flash}:{lang:Lang;flash:(s:string)=>void}){
  const vi=lang==='vi';const[selectedId,setSelectedId]=useState(complaints[0]?.id||'');const[states,setStates]=useState<Record<string,any>>({});const selected=complaints.find(c=>c.id===selectedId)||complaints[0]
  useEffect(()=>{loadAppState('complaint:').then(s=>setStates(s)).catch(()=>{})},[])
  const save=async(status:string)=>{const patch={status,updatedAt:new Date().toISOString()};setStates(s=>({...s,[`complaint:${selected.id}`]:patch}));await saveAppState(`complaint:${selected.id}`,patch);await logActivity('complaint_status_changed','complaint',selected.id,patch);flash(vi?'Khiếu nại đã được cập nhật.':'Complaint updated.')}
  return <div className="admin-body"><div className="master-detail"><section className="panel complaint-list"><div className="panel-title"><div><h2>{vi?'Danh sách khiếu nại':'Complaint queue'}</h2><p>{complaints.length} {vi?'hồ sơ':'cases'}</p></div></div>{complaints.map(c=><button key={c.id} className={c.id===selected.id?'selected':''} onClick={()=>setSelectedId(c.id)}><div><b>{c.id}</b><span>{c.product}</span><small>{txt(c.reason,lang)}</small></div><ChevronRight size={16}/></button>)}</section><section className="panel complaint-detail"><span className="eyebrow"><AlertTriangle size={15}/>{selected.id}</span><h2>{selected.product}</h2><p className="lead">{txt(selected.reason,lang)}</p><div className="case-timeline"><div><span>1</span><div><b>{vi?'Tiếp nhận':'Received'}</b><small>06/09/2026 · 09:18</small></div></div><div><span>2</span><div><b>{vi?'Đối chiếu bằng chứng':'Evidence comparison'}</b><small>06/09/2026 · 10:06</small></div></div><div><span>3</span><div><b>{vi?'Trạng thái hiện tại':'Current status'}</b><small>{states[`complaint:${selected.id}`]?.status||txt(selected.status,lang)}</small></div></div></div><div className="product-actions"><button className="ghost" onClick={()=>save(vi?'Đang kiểm duyệt':'Under review')}><Eye size={16}/>{vi?'Đang kiểm duyệt':'Under review'}</button><button className="secondary" onClick={()=>save(vi?'Chờ doanh nghiệp bổ sung':'Awaiting brand evidence')}><FileSearch size={16}/>{vi?'Yêu cầu bổ sung':'Request evidence'}</button><button className="primary" onClick={()=>save(vi?'Đã xử lý':'Resolved')}><CheckCircle2 size={16}/>{vi?'Đánh dấu đã xử lý':'Resolve'}</button></div></section></div></div>
}

function Reports({lang,flash,products}:{lang:Lang;flash:(s:string)=>void;products:Product[]}){
  const vi=lang==='vi';const[period,setPeriod]=useState('30');const[activities,setActivities]=useState<ActivityRow[]>([])
  useEffect(()=>{loadActivities(12).then(setActivities).catch(()=>{})},[])
  const metrics={products:products.length,verified:products.filter(p=>p.status==='verified').length,reviews:products.reduce((s,p)=>s+p.verifiedReviews,0),avg:Math.round(products.reduce((s,p)=>s+p.trustScore,0)/Math.max(1,products.length)),scans:activities.filter(a=>a.action_type==='ai_scan_completed').length}
  const triggerDownload=(name:string,type:string,content:string)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
  const csv=async()=>{const lines=['SKU,Product,Status,Trust Score,Verified Reviews',...products.map(p=>[p.sku,`"${txt(p.name,lang).replaceAll('"','""')}"`,p.status,p.trustScore,p.verifiedReviews].join(','))];triggerDownload(`cosmo-report-${period}d.csv`,'text/csv;charset=utf-8',lines.join('\n'));await logActivity('report_exported','report',period,{format:'csv',period});flash(vi?'Đã tải báo cáo CSV.':'CSV report downloaded.')}
  const json=async()=>{const payload={generatedAt:new Date().toISOString(),periodDays:Number(period),metrics,products:products.map(p=>({sku:p.sku,name:txt(p.name,lang),status:p.status,trustScore:p.trustScore,verifiedReviews:p.verifiedReviews})),activities};triggerDownload(`cosmo-report-${period}d.json`,'application/json',JSON.stringify(payload,null,2));await logActivity('report_exported','report',period,{format:'json',period});flash(vi?'Đã tải báo cáo JSON.':'JSON report downloaded.')}
  return <div className="admin-body"><div className="toolbar"><div className="chips">{['7','30','90'].map(d=><button key={d} className={period===d?'active':''} onClick={()=>setPeriod(d)}>{d} {vi?'ngày':'days'}</button>)}</div><div className="report-actions"><button className="ghost" onClick={()=>window.print()}><FileCheck2 size={16}/>{vi?'In / lưu PDF':'Print / Save PDF'}</button><button className="secondary" onClick={json}><Database size={16}/>JSON</button><button className="primary" onClick={csv}><BarChart3 size={16}/>{vi?'Tải CSV':'Download CSV'}</button></div></div><div className="kpi-grid reports-kpi"><div className="kpi-card"><strong>{metrics.products}</strong><span>{vi?'Sản phẩm':'Products'}</span></div><div className="kpi-card"><strong>{metrics.verified}</strong><span>{vi?'Đủ bằng chứng':'Verified'}</span></div><div className="kpi-card"><strong>{metrics.avg}/100</strong><span>{vi?'Điểm TB':'Avg score'}</span></div><div className="kpi-card"><strong>{metrics.reviews}</strong><span>{vi?'Review xác minh':'Verified reviews'}</span></div><div className="kpi-card"><strong>{metrics.scans}</strong><span>{vi?'Lượt AI gần đây':'Recent AI scans'}</span></div></div><section className="panel"><div className="panel-title"><div><h2>{vi?'Hoạt động gần đây':'Recent activity'}</h2><p>{vi?'Dữ liệu được đọc trực tiếp từ lịch sử workspace.':'Read directly from workspace history.'}</p></div></div><div className="activity-feed">{activities.length?activities.map(a=><div key={a.id}><span className="pulse-dot"></span><div><b>{a.action_type.replaceAll('_',' ')}</b><small>{a.entity_type}{a.entity_id?` · ${a.entity_id}`:''} · {new Date(a.created_at).toLocaleString(lang==='vi'?'vi-VN':'en-US')}</small></div></div>):<div className="empty-line">{vi?'Chưa có hoạt động mới.':'No recent activity.'}</div>}</div></section></div>
}

function Integrations({lang,flash}:{lang:Lang;flash:(s:string)=>void}){
  const vi=lang==='vi';const specs=[{key:'shopify',name:'Shopify',desc:vi?'Đồng bộ sản phẩm, đơn hàng và trạng thái giao hàng.':'Sync products, orders and delivery status.'},{key:'woocommerce',name:'WooCommerce',desc:vi?'Đồng bộ catalog và đơn hàng qua REST API.':'Sync catalog and orders via REST API.'},{key:'api',name:'COSMO API',desc:vi?'Kết nối website, ERP hoặc hệ thống nội bộ qua API.':'Connect websites, ERP or internal systems via API.'}];const[state,setState]=useState<Record<string,any>>({});const[testing,setTesting]=useState('')
  useEffect(()=>{loadAppState('integration:').then(setState).catch(()=>{})},[])
  const persist=async(key:string,value:any)=>{const next={...(state[`integration:${key}`]||{}),...value};setState(s=>({...s,[`integration:${key}`]:next}));await saveAppState(`integration:${key}`,next);await logActivity('integration_updated','integration',key,next)}
  const toggle=async(key:string)=>{const connected=!(state[`integration:${key}`]?.connected);await persist(key,{connected,lastSync:connected?new Date().toISOString():state[`integration:${key}`]?.lastSync});flash(connected?(vi?'Đã kết nối tích hợp.':'Integration connected.'):(vi?'Đã ngắt kết nối.':'Integration disconnected.'))}
  const sync=async(key:string)=>{await persist(key,{connected:true,lastSync:new Date().toISOString()});flash(vi?'Đồng bộ hoàn tất.':'Sync complete.')}
  const test=async(key:string)=>{setTesting(key);try{const{data,error}=await supabase.from('cosmo_products').select('id').limit(1);if(error)throw error;await logActivity('integration_connection_test','integration',key,{success:Boolean(data)});flash(vi?'Kết nối dữ liệu hoạt động bình thường.':'Data connection is healthy.')}catch{flash(vi?'Không thể kết nối dữ liệu.':'Data connection failed.')}finally{setTesting('')}}
  return <div className="admin-body"><section className="panel"><div className="panel-title"><div><h2>{vi?'Kết nối hệ thống':'System integrations'}</h2><p>{vi?'Trạng thái kết nối và lần đồng bộ gần nhất được lưu trong workspace.':'Connection state and last sync are stored in the workspace.'}</p></div></div><div className="integration-grid">{specs.map(s=>{const value=state[`integration:${s.key}`]||{};return <div className="integration-card" key={s.key}><div className="integration-icon"><Link2/></div><div><h3>{s.name}</h3><p>{s.desc}</p><span className={value.connected?'integration-status on':'integration-status'}><span></span>{value.connected?(vi?'Đã kết nối':'Connected'):(vi?'Chưa kết nối':'Not connected')}</span>{value.lastSync&&<small>{vi?'Đồng bộ gần nhất':'Last sync'}: {new Date(value.lastSync).toLocaleString(lang==='vi'?'vi-VN':'en-US')}</small>}</div><div className="integration-actions"><button className="ghost" onClick={()=>test(s.key)} disabled={testing===s.key}>{testing===s.key?(vi?'Đang kiểm tra…':'Testing…'):(vi?'Kiểm tra':'Test')}</button>{value.connected&&<button className="secondary" onClick={()=>sync(s.key)}><RefreshCcw size={15}/>{vi?'Đồng bộ':'Sync'}</button>}<button className={value.connected?'ghost':'primary'} onClick={()=>toggle(s.key)}>{value.connected?(vi?'Ngắt kết nối':'Disconnect'):(vi?'Kết nối':'Connect')}</button></div></div>})}</div></section></div>
}

function Scope({lang}:{lang:Lang}){const vi=lang==='vi';return <div className="admin-body"><section className="scope-hero panel"><span className="eyebrow"><ShieldCheck/>COSMO TRUST MODEL</span><h2>{vi?'COSMO không phải “máy phán thật/giả”.':'COSMO is not a “truth machine”.'}</h2><p>{vi?'Nền tảng tổ chức bằng chứng nhiều nguồn, phân tích tín hiệu rủi ro, yêu cầu con người xác nhận và công khai lịch sử đủ để người mua tự kiểm tra.':'The platform organizes multi-source evidence, analyzes risk signals, requires human confirmation and exposes enough history for customers to inspect.'}</p></section><div className="scope-grid"><ScopeCard n="01" icon={Database} title={vi?'Ghi nhận nguồn & phiên bản':'Source & version recording'} text={vi?'Hash chỉ giúp nhận biết dữ liệu đã thay đổi sau khi ghi nhận; hash không chứng minh nội dung ban đầu là đúng.':'A hash helps detect post-recording changes; it does not prove the original content was true.'}/><ScopeCard n="02" icon={Bot} title={vi?'Phân tích tín hiệu AI':'AI signal analysis'} text={vi?'Điểm tin cậy là độ chắc chắn với tín hiệu kỹ thuật, không phải xác suất thật/giả tuyệt đối.':'Confidence refers to technical signals, not an absolute true/false probability.'}/><ScopeCard n="03" icon={Eye} title={vi?'Người kiểm duyệt':'Human confirmation'} text={vi?'Các case cần xem lại được chuyển người kiểm duyệt trước khi công bố trạng thái quan trọng.':'Review cases are escalated to a human before critical status publication.'}/><ScopeCard n="04" icon={Globe2} title={vi?'Công khai có chọn lọc':'Selective public disclosure'} text={vi?'Khách chỉ thấy dữ liệu cần để ra quyết định, không thấy mật khẩu, thanh toán hay dữ liệu nội bộ nhạy cảm.':'Customers see decision-relevant data, not passwords, payment data or sensitive internal records.'}/></div><section className="panel limitations"><h2>{vi?'Phạm vi vận hành & nguyên tắc phân tích':'Limitations to state clearly when pitching'}</h2><ul><li>{vi?'Video ngắn, độ phân giải thấp hoặc nén mạnh làm giảm độ tin cậy của tín hiệu.':'Short, low-resolution or heavily compressed video reduces signal reliability.'}</li><li>{vi?'Review xác minh giao dịch không đồng nghĩa review luôn khách quan.':'Transaction verification does not guarantee a review is objective.'}</li><li>{vi?'COSMO không thay cơ quan giám định, cơ quan quản lý hay phán quyết pháp lý.':'COSMO does not replace inspectors, regulators or legal judgment.'}</li><li>{vi?'KPI kinh doanh trong prototype là dữ liệu minh họa, phải pilot và A/B test.':'Business KPIs in the prototype are illustrative and require pilots and A/B tests.'}</li></ul></section></div>}
function ScopeCard({n,icon:Icon,title,text}:{n:string;icon:any;title:string;text:string}){return <div className="scope-card"><small>{n}</small><span><Icon/></span><h3>{title}</h3><p>{text}</p></div>}

function StatusBadge({status,lang}:{status:TrustStatus;lang:Lang}){const m=statusMeta[status];return <span className={`badge ${m.cls}`}><span></span>{lang==='vi'?m.vi:m.en}</span>}

function EvidenceDrawer({lang,product,onClose,go}:{lang:Lang;product:Product;onClose:()=>void;go:(s:string)=>void}){const vi=lang==='vi';const rows=product.evidence.length?product.evidence:[{id:'fallback',title:{vi:'Bộ ảnh thực tế',en:'Real imagery set'},type:'image' as const,source:{vi:'Doanh nghiệp',en:'Brand'},verified:true,date:'2026-09-05',note:{vi:'Đã kiểm tra nguồn và ngày cập nhật.',en:'Source and update date checked.'}}];return <div className="drawer-backdrop" onMouseDown={e=>{if(e.currentTarget===e.target)onClose()}}><aside className="drawer"><button className="drawer-x" onClick={onClose}><X/></button><div className="drawer-title"><ShieldCheck/><div><small>COSMO TRUST WIDGET</small><h2>{vi?'Hồ sơ minh bạch':'Transparency profile'}</h2></div></div><div className="drawer-product"><img src={product.image}/><div><b>{txt(product.name,lang)}</b><small>{product.sku}</small></div><StatusBadge status={product.status} lang={lang}/></div><div className="drawer-score"><strong>{product.trustScore}/100</strong><span>{vi?'Điểm minh bạch hiện tại':'Current transparency score'}</span></div><h3>{vi?'Bạn đang thấy gì?':'What are you seeing?'}</h3><div className="drawer-highlights"><div><CheckCircle2/><span>{product.realPhotos} {vi?'ảnh thực tế đã liên kết':'linked real photos'}</span></div><div><ShoppingBag/><span>{product.verifiedReviews} {vi?'review từ đơn đã giao':'reviews from delivered orders'}</span></div><div><Activity/><span>{vi?'Lịch sử nguồn và cập nhật':'Source and update history'}</span></div></div><h3>{vi?'Bằng chứng nổi bật':'Key evidence'}</h3><div className="evidence-list drawer-list">{rows.slice(0,4).map(e=><div className="evidence-row" key={e.id}><span className="evidence-icon"><FileCheck2/></span><div className="evidence-copy"><b>{txt(e.title,lang)}</b><small>{txt(e.source,lang)} · {e.date}</small></div></div>)}</div><button className="primary full large" onClick={()=>{onClose();go(`/trust/${product.slug}`)}}>{vi?'Xem hồ sơ đầy đủ':'View full profile'}<ArrowRight/></button></aside></div>}

function QrModal({lang,product,onClose}:{lang:Lang;product:Product;onClose:()=>void}){const vi=lang==='vi';const origin=location.origin;const url=`${origin}/trust/${product.slug}`;return <div className="modal-backdrop"><div className="modal qr-modal"><button className="modal-x" onClick={onClose}><X/></button><span className="qr-icon"><QrCode/></span><h2>{vi?'Quét để mở hồ sơ minh bạch':'Scan to open the transparency profile'}</h2><p>{vi?'QR được tạo động từ đường dẫn public hiện tại. Sau khi deploy Cloudflare, QR sẽ tự trỏ về domain public.':'The QR is generated dynamically from the current public URL. After Cloudflare deployment it automatically points to the public domain.'}</p><div className="qr-box"><QRCodeSVG value={url} size={220} includeMargin level="M"/></div><code className="qr-url">{url}</code><button className="secondary full" onClick={()=>navigator.clipboard.writeText(url)}><Copy/>{vi?'Sao chép liên kết':'Copy link'}</button></div></div>}

function Tour({lang,onClose,go}:{lang:Lang;onClose:()=>void;go:(p:string)=>void}){const vi=lang==='vi';const steps=[['/shop',vi?'1. Website khách hàng':'1. Customer website',vi?'Xem catalog 10 sản phẩm và trạng thái khác nhau.':'Browse 10 products with different states.'],['/shop/nuoc-tay-trang-bi-dao-500ml',vi?'2. Trust Widget':'2. Trust Widget',vi?'Mở bằng chứng ngay sát nút mua.':'Open evidence next to the purchase CTA.'],['/trust/nuoc-tay-trang-bi-dao-500ml',vi?'3. Hồ sơ công khai':'3. Public profile',vi?'Xem nguồn, lịch sử và QR.':'Inspect sources, history and QR.'],['/admin/ai',vi?'4. AI Lab':'4. AI Lab',vi?'Chạy video, marker và luồng xác nhận.':'Run video, markers and confirmation flow.'],['/admin/widget',vi?'5. Widget Builder':'5. Widget Builder',vi?'Cấu hình và kiểm tra widget trên website.':'Configure and verify the widget on the website.'],['/admin/reports',vi?'6. Báo cáo':'6. Reports',vi?'Đọc KPI minh họa đúng phạm vi.':'Read illustrative KPIs with proper scope.']];return <div className="modal-backdrop"><div className="modal tour-modal"><button className="modal-x" onClick={onClose}><X/></button><span className="tour-spark"><Sparkles/></span><h2>{vi?'Trình diễn COSMO trong ~3 phút':'COSMO ~3 minute guided demo'}</h2><p>{vi?'Mỗi bước mở đúng màn hình để bạn thuyết trình không bị lệch giữa lời nói và thao tác.':'Each step opens the right screen so narration stays aligned with the interface.'}</p><div className="tour-steps">{steps.map(([path,title,desc])=><button key={path} onClick={()=>go(path)}><span><Play/></span><div><b>{title}</b><small>{desc}</small></div><ChevronRight/></button>)}</div></div></div>}

export default App
